-fn stat_line(file: &FileDiff) -> String {
-    let path = match &file.old_path {
-        Some(old) => format!("{old} => {}", file.path),
-        None => file.path.clone(),
-    };
-    match file.lines {
-        Some((added, deleted)) => format!("{path} | +{added} -{deleted}\n"),
-        None => format!("{path} | binary\n"),
-    }
-}
