+    } else if CONFIG_EXTENSIONS.contains(&extension)
+        || name.starts_with('.')
+        || matches!(lower.as_str(), "dockerfile" | "makefile")
+    {
+        FileKind::Config
+    } else {
+        FileKind::Source
+    }
+}
