+#[derive(Debug, Clone, Default, PartialEq, Eq)]
+pub struct CompactDiff {
+    /// One line per file, always complete for the files it lists.
+    pub stat: String,
+    /// The hunks that fit, grouped per file.
+    pub patch: String,
+    /// Files whose hunks were dropped or cut short.
+    pub truncated: usize,
