+/// only a model trained without them can do without.
+pub fn prompt_rules(file: &Path) -> PromptRules {
+    REGISTRY
+        .iter()
+        .find(|model| is_installed(&model.gguf, file))
+        .map_or(PromptRules::Full, |model| model.rules)
