+/// is called with the bytes downloaded so far, about twice a second.
+pub fn install_gguf(
+    model: &'static Model,
+    dir: &Path,
+    base: &str,
+    mut progress: impl FnMut(u64),
+) -> Result<PathBuf, ModelError> {
+    let gguf = &model.gguf;
+    let file = dir.join(gguf.file);
+    if is_installed(gguf, &file) {
+        return Ok(file);
+    }
